    {
      "id": 1,
      "claim": "For a concave mirror the mirror equation is 1/f = 1/do + 1/di, with f>0.",
      "evidence": "Standard thin‑mirror formula for spherical mirrors (derived from geometry of reflection).",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Linear magnification is m = -di/do.",
      "evidence": "Definition of magnification for mirrors (image height / object height = -image distance / object distance).",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "When the object is at infinity (do → ∞), the image distance di = f.",
      "evidence": "Set 1/do → 0 in the mirror equation → 1/di = 1/f → di = f.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "As the object distance do decreases from a large value toward f (but stays > f), the image distance di increases without bound (di → ∞).",
      "evidence": "From 1/di = 1/f – 1/do: as do → f⁺, 1/do → 1/f⁻, so the right‑hand side → 0⁺, giving di → +∞.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "When di grows very large while do remains finite (>f), the magnitude of magnification |m| = |di/do| becomes very large, so the image height increases (the image gets taller).",
      "evidence": "Substituting the expression di = f·do/(do‑f) into |m| = di/do yields |m| = f/(do‑f); as do → f⁺ the denominator → 0⁺, so |m| → ∞.",
      "weight": 0.20,
      "depends_on": [2, 4]
    }
  ],
  "answer": "B",
  "confidence": 0.96,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "The image size increases (gets taller) as the object approaches the focal point, not shorter."
    },
    {
      "answer": "C",
      "reason_rejected": "The image distance increases (moves away), not decreases (toward the mirror)."
    },
    {
      "answer": "D",
      "reason_rejected": "Same reason as C: the image moves away, not toward the mirror."
    }
  ]
